import sys


def before(a, b):
    if a[1] != b[1]:
        return a[1] > b[1]
    if a[2] != b[2]:
        return a[2] < b[2]
    return a[0] < b[0]


def main():
    lines = sys.stdin.read().splitlines()
    n = int(lines[0])
    rest = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        rest.append((parts[0], int(parts[1]), int(parts[2])))
    out = []
    while rest:
        best = 0
        for j in range(1, len(rest)):
            if before(rest[j], rest[best]):
                best = j
        out.append(rest.pop(best)[0])
    print("\n".join(out))


main()
